sp_widget.client_script:
function($scope, $location) {
 $scope.goTo = function(url) {
    // Abre o link em uma nova aba
    window.open(url, '_blank');
  };

	  $scope.goToPage = function(id) {
    $location.url("?id=" + id);
  };

	 $scope.goToPageBlank = function(id) {
    window.open("?id=" + id, '_blank');
  };

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

}

sp_widget.css:
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Roboto Flex', sans-serif !important;
  	font-weight: 400;
}

.fiscal-widget-container {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
    display: flex;
    flex-wrap: nowrap;
    justify-content: center;
    padding: 2rem;
    gap: 2rem;
    margin: 0 auto 3rem;
    max-width: 100%;
    overflow-x: auto;
}

.fiscal-card {
  font-family: 'Roboto Flex', sans-serif !important;
  				font-weight: 400;
    flex: 0 0 auto;
    width: 260px;
    height: 260px;
    background: white;
    border-radius: 8px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
    text-align: center;
    padding: 1.5rem 1rem;
    cursor: pointer;
    transition: transform 0.2s, background-color 0.3s;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
}

.fiscal-card:hover {
    background-color: #d3d3d3;
    transform: scale(1.05);
}

.fiscal-card img {
    height: 10rem;
    width: auto;
    max-width: 90%;
    object-fit: contain;
    margin: 1.5rem 0;
    transition: opacity 0.3s;
}

.fiscal-card:hover img {
    opacity: 0;
}

.fiscal-label {
  font-family: 'Roboto Flex', sans-serif !important;
  				font-weight: 400;
    font-size: 1.8rem;
    font-weight: bold;
    margin-bottom: 0.8rem;
    position: relative;
    z-index: 1;
    transition: color 0.3s;
}

.fiscal-card:hover .fiscal-label {
    color: black;
}

.fiscal-info {
  font-family: 'Roboto Flex', sans-serif !important;
  				font-weight: 400;
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: #d3d3d3;
    color: black;
    font-size: 1.9rem;
    padding: 1.5rem;
    text-align: center;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s;
}

.fiscal-card:hover .fiscal-info {
    opacity: 1;
    pointer-events: auto;
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* Breakpoints Responsivos */
/* 1400px e abaixo: Começa o layout responsivo 2x3 */
@media (max-width: 1500px) {
    .fiscal-widget-container {
        flex-wrap: wrap;
        overflow-x: visible;
        max-width: 1300px;
    }

    .fiscal-card {
        flex: 1 1 calc(50% - 2rem);
        min-width: 260px;
        max-width: 550px;
        width: auto;
    }

  .fiscal-info{
    font-size: 1.9rem;
    align-items: center;
  }

}

/* 1200px: Monitores menores e tablets grandes */
@media (max-width: 1200px) {
    .fiscal-widget-container {
        padding: 1.5rem;
        gap: 1.5rem;
    }

    .fiscal-card {
        flex: 1 1 calc(50% - 1.5rem);
        height: 240px;
    }

    .fiscal-label {
        font-size: 1.6rem;
    }

    .fiscal-info {
        font-size: 1.9rem;
        padding: 1.2rem;
        padding-bottom: 2.5rem;
    }
}

/* 992px: Tablets */
@media (max-width: 992px) {
    .fiscal-widget-container {
        padding: 1.2rem;
        gap: 1.2rem;
    }

    .fiscal-card {
        padding: 1.2rem 1rem;
        height: 190px;
    }

    .fiscal-card img {
        height: 8rem;
    }

    .fiscal-label {
        font-size: 1.3rem;
    }

    .fiscal-info {
        padding: 1rem;
        font-size: 1.5rem;
    }
}

/* 768px: Tablets pequenos/smartphones */
@media (max-width: 768px) {
    .fiscal-widget-container {
        padding: 1rem;
        gap: 1rem;
        margin-bottom: 2rem;
    }

    .fiscal-card {
        flex: 1 1 100%;
        max-width: 500px;
        height: 220px;
        padding: 1rem;
    }

    .fiscal-card img {
        height: 8rem;
        margin: 1rem 0;
    }

    .fiscal-label {
        font-size: 1.5rem;
    }

    .fiscal-info {
        padding: 1rem;
        font-size: 1.9rem;
        padding-bottom: 2rem;
        align-items: center;
    }
}

/* 480px: Smartphones */
@media (max-width: 480px) {
    .fiscal-widget-container {
        padding: 0.8rem;
        gap: 0.8rem;
    }

    .fiscal-card {
        min-width: 240px;
        height: 200px;
        padding: 0.8rem;
    }

    .fiscal-card img {
        height: 7rem;
    }

    .fiscal-label {
        font-size: 1.3rem;
    }

    .fiscal-info {
        padding: 0.8rem;
        font-size: 1.9rem;
        display: flex;
        align-items: center;
        justify-content: center;
        padding-bottom: 1.5rem;
    }
}

/* 375px: iPhone SE e dispositivos menores */
@media (max-width: 375px) {
    .fiscal-widget-container {
        padding: 0.5rem;
        gap: 0.6rem;
    }

    .fiscal-card {
        height: 180px;
        padding: 0.7rem;
    }

    .fiscal-card img {
        height: 6rem;
    }

    .fiscal-label {
        font-size: 1.2rem;
    }

    .fiscal-info {
        padding: 0.7rem;
        font-size: 1.9rem;
        align-items: flex-end;
        padding-bottom: 1.5rem;
    }
}

/* Para telas muito largas - melhorar visualização horizontal */
@media (min-width: 1800px) {
    .fiscal-widget-container {
        justify-content: center;
        gap: 3rem;
    }

    .fiscal-card {
        width: 280px;
    }
      .fiscal-info {
        padding: 0.7rem;
        font-size: 1.9rem;
        align-items: center;
        padding-bottom: 1.5rem;
	}



/* Suporte a dispositivos com botões de toque - para melhor usabilidade */
@media (hover: none) {
    .fiscal-info {
        opacity: 0.95;
        background-color: rgba(211, 211, 211, 0.95);
        align-items: flex-end;
        padding-bottom: 2.5rem;
    }

    .fiscal-card:active {
        transform: scale(0.98);
    }
}
